CREATE OR REPLACE FUNCTION public.start_pet_training(wanted_pet text, stat_type text DEFAULT 'attack'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ declare up public.user_pets;p public.profiles;cost numeric(12,2);mins int;lvl int; begin select * into p from public.profiles where id=auth.uid() for update; if p.id is null or p.is_banned then raise exception 'Zugriff gesperrt';end if; select * into up from public.user_pets where user_id=auth.uid() and pet_id=wanted_pet for update; if up.pet_id is null then raise exception 'Dieser Begleiter gehört dir nicht';end if; if up.training_ends_at is not null then raise exception 'Begleitertraining läuft bereits oder wartet auf Abschluss';end if; if stat_type not in ('attack','defense','mitleid') then raise exception 'Unbekannter Trainingswert';end if; lvl:=case stat_type when 'attack' then up.attack_level when 'defense' then up.defense_level else up.mitleid_level end; if lvl>=50 then raise exception 'Dieser Wert ist bereits voll trainiert';end if; cost:=round(5*power(lvl::numeric,1.55),2);mins:=greatest(2,lvl*5); if p.money<cost then raise exception 'Dafür reicht deine Kohle nicht';end if; update public.profiles set money=money-cost where id=p.id returning * into p; update public.user_pets set training_ends_at=now()+make_interval(mins=>mins),training_stat=stat_type where user_id=p.id and pet_id=wanted_pet returning * into up; return jsonb_build_object('cost',cost,'minutes',mins,'stat',stat_type,'pet',to_jsonb(up),'profile',to_jsonb(p)); end $function$;
